// ── Subsystem 1: Cart ─────────────────────────────────────────
class CartService {
  validate(cartId) {
    if (!cartId) throw new Error('cartId required');
    console.log(`[Cart] Validating ${cartId}`);
    return true;
  }
  getItems(cartId) {
    console.log(`[Cart] Fetching items for ${cartId}`);
    return [
      { id: 'sku-1', name: 'Widget', price: 19.99 },
      { id: 'sku-2', name: 'Gadget', price: 34.99 },
    ];
  }
  getTotal(items) {
    return items.reduce((sum, i) => sum + i.price, 0);
  }
}

// ── Subsystem 2: Inventory ────────────────────────────────────
class InventoryService {
  reserve(items) {
    console.log(`[Inventory] Reserving ${items.length} item(s)`);
    // May throw if out of stock
  }
  release(items) {
    console.log(`[Inventory] Releasing ${items.length} item(s)`);
  }
}

// ── Subsystem 3: Payment ──────────────────────────────────────
class PaymentGateway {
  charge(userId, amount) {
    console.log(`[Payment] Charging user ${userId} $${amount.toFixed(2)}`);
    if (amount <= 0) throw new Error('Invalid amount');
    return { receiptId: `REC-${Date.now()}`, amount, userId };
  }
  refund(receiptId) {
    console.log(`[Payment] Refunding ${receiptId}`);
  }
}

// ── Subsystem 4: Email ────────────────────────────────────────
class EmailService {
  sendConfirmation(userId, receipt) {
    console.log(`[Email] Confirmation → user ${userId}, receipt ${receipt.receiptId}`);
  }
  sendCancellation(userId) {
    console.log(`[Email] Cancellation → user ${userId}`);
  }
}

// ── Facade: inject subsystems for testability ─────────────────
class OrderFacade {
  constructor({
    cart      = new CartService(),
    inventory = new InventoryService(),
    payment   = new PaymentGateway(),
    email     = new EmailService(),
  } = {}) {
    this._cart      = cart;
    this._inventory = inventory;
    this._payment   = payment;
    this._email     = email;
  }

  // ── Main operation: coordinate four subsystems ────────────
  async placeOrder(cartId, userId) {
    if (!this._cart.validate(cartId)) {
      throw new Error('Cart validation failed');
    }

    const items = this._cart.getItems(cartId);
    const total = this._cart.getTotal(items);

    // Reserve inventory first; if payment fails we must release
    this._inventory.reserve(items);

    let receipt;
    try {
      receipt = this._payment.charge(userId, total);
    } catch (paymentError) {
      // ── Compensation: undo the reservation ────────────────
      this._inventory.release(items);
      throw new Error(`Payment failed; inventory released. ${paymentError.message}`);
    }

    // Non-critical — do not roll back order if email fails
    try {
      this._email.sendConfirmation(userId, receipt);
    } catch {
      console.warn('[OrderFacade] Email failed but order succeeded');
    }

    return receipt;
  }

  // ── Cancellation: reverse the happy path ──────────────────
  async cancelOrder({ receiptId, userId, items }) {
    this._payment.refund(receiptId);
    this._inventory.release(items);
    try {
      this._email.sendCancellation(userId);
    } catch {
      console.warn('[OrderFacade] Cancellation email failed');
    }
  }
}

// ── Client: two methods, zero subsystem knowledge ─────────────
const orders = new OrderFacade();
const receipt = await orders.placeOrder('cart-99', 'user-42');
console.log('Order placed:', receipt.receiptId);

