// ── Full testable facade with interface-like duck-typing ──────

// 'Interface' contracts (JS duck-typed; TypeScript would use interface keyword)
const ICart      = { validate: null, getItems: null, getTotal: null };
const IInventory = { reserve: null, release: null };
const IPayment   = { charge: null, refund: null };
const IEmail     = { sendConfirmation: null, sendCancellation: null };

// ── Test doubles (pure in-memory fakes) ───────────────────────
const fakeCart = {
  validate: (cartId) => cartId === 'valid-cart',
  getItems: (cartId) => [{ id: 'a', name: 'Widget', price: 10 }],
  getTotal: (items)  => items.reduce((s, i) => s + i.price, 0),
};

const fakeInventory = {
  reserved: [],
  reserve:  function(items) { this.reserved.push(...items); },
  release:  function(items) { this.reserved = this.reserved.filter(r => !items.includes(r)); },
};

const fakePayment = {
  charged: [],
  charge:  function(userId, amount) {
    const r = { receiptId: 'FAKE-REC-1', amount, userId };
    this.charged.push(r);
    return r;
  },
  refund: function(id) { this.charged = this.charged.filter(c => c.receiptId !== id); },
};

const fakeEmail = {
  sent: [],
  sendConfirmation:  (userId, receipt) => fakeEmail.sent.push({ type: 'confirm', userId }),
  sendCancellation:  (userId)          => fakeEmail.sent.push({ type: 'cancel',  userId }),
};

// ── Test: placeOrder calls all four subsystems in sequence ────
async function testPlaceOrder() {
  const facade = new OrderFacade({
    cart:      fakeCart,
    inventory: fakeInventory,
    payment:   fakePayment,
    email:     fakeEmail,
  });

  const receipt = await facade.placeOrder('valid-cart', 'u-1');

  console.assert(receipt.receiptId === 'FAKE-REC-1',     'receipt returned');
  console.assert(fakeInventory.reserved.length === 1,    'inventory reserved');
  console.assert(fakePayment.charged.length === 1,       'payment charged');
  console.assert(fakeEmail.sent[0].type === 'confirm',   'confirmation sent');
  console.log('testPlaceOrder: PASS');
}

// ── Test: payment failure releases inventory ──────────────────
async function testPaymentFailureCompensates() {
  const brokenPayment = {
    charge: () => { throw new Error('Card declined'); },
    refund: () => {},
  };
  const inv = { reserved: [], reserve(items) { this.reserved.push(...items); }, release(items) { this.reserved = []; } };

  const facade = new OrderFacade({
    cart:      fakeCart,
    inventory: inv,
    payment:   brokenPayment,
    email:     fakeEmail,
  });

  try {
    await facade.placeOrder('valid-cart', 'u-2');
    console.assert(false, 'should have thrown');
  } catch (e) {
    console.assert(inv.reserved.length === 0, 'inventory released on payment failure');
    console.log('testPaymentFailureCompensates: PASS');
  }
}

await testPlaceOrder();
await testPaymentFailureCompensates();

// ── Static module facade (TypeScript-style in plain JS) ───────
// File structure:
//   auth/
//     token-service.js    ← internal
//     session-store.js    ← internal
//     crypto-util.js      ← internal
//     auth-facade.js      ← coordinates internals
//     index.js            ← public API (module facade)

// auth/token-service.js
class TokenService {
  generate(userId) { return `tok_${userId}_${Date.now()}`; }
  verify(token)    { return token.startsWith('tok_'); }
  invalidate(token){ /* blacklist logic */ }
}

// auth/session-store.js
class SessionStore {
  constructor() { this._sessions = new Map(); }
  save(token, userId)  { this._sessions.set(token, userId); }
  load(token)          { return this._sessions.get(token); }
  delete(token)        { this._sessions.delete(token); }
}

// auth/auth-facade.js
class AuthFacade {
  constructor() {
    this._tokens   = new TokenService();
    this._sessions = new SessionStore();
  }

  login(userId) {
    const token = this._tokens.generate(userId);
    this._sessions.save(token, userId);
    return { token };
  }

  logout(token) {
    this._tokens.invalidate(token);
    this._sessions.delete(token);
  }

  authenticate(token) {
    if (!this._tokens.verify(token)) throw new Error('Invalid token');
    const userId = this._sessions.load(token);
    if (!userId) throw new Error('Session not found');
    return { userId };
  }
}

// auth/index.js  ← module facade: expose only the public contract
const _facade = new AuthFacade();

export const login        = (userId) => _facade.login(userId);
export const logout       = (token)  => _facade.logout(token);
export const authenticate = (token)  => _facade.authenticate(token);
// TokenService and SessionStore are NOT exported — they are private

// ── Caller: depends only on the public module API ─────────────
import { login, logout, authenticate } from './auth/index.js';

const { token } = login('user-42');
console.log('Logged in:', token);

const { userId } = authenticate(token);
console.log('Authenticated as:', userId);

logout(token);
console.log('Logged out');
